head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setRowPosition]<br/>Row 의 인덱스값을 사용하여 DataList 모듈의 특정 Row 를 선택합니다.",
    "validation" : [
        "DataList 모듈이 InputBox 와 같은 단일 컴포넌트에 ref 속성으로 바인드 되었을때 setRowPostion() 메소드로 Row 선택 변경 시 변경된 Row 의 값이 바인드 된 컴포넌트에 반영됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("onrowpositionchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====onrowpositionchange=====");});

    // gridView 생성
    // $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true" focusMode="row" syncRowPositionOption="style" ev:oncellclick="scwin.gridView1_oncellclick"', '', 'gridView1');

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.col1" style="width:200px;height:30px;"', '', 'input1');
}



scwin.btn_getRowPosition_onclick = function (e) {
    let rtn = target1.getRowPosition();

    wf_body_bottom.getObj("scwin").setReturnValue("getRowPosition: " + rtn);
};



scwin.btn_getInputValue = function () {
    let rtn = input1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("input1.value: " + rtn);
}



scwin.btn_setRowPosition_onclick = function (e) {
    let rowIndex = par_rowIndex.getText();

    target1.setRowPosition(rowIndex);

    scwin.btn_getRowPosition_onclick();
    scwin.btn_getInputValue();
};
